package com.wams.quotation;
import com.wams.entity.*;import com.wams.enums.Role;import com.wams.exception.*;import com.wams.operations.*;import com.wams.quotation.dto.*;import com.wams.repository.*;import com.wams.security.AuthenticatedUserProvider;import com.wams.vendor.*;import lombok.RequiredArgsConstructor;import org.springframework.security.access.AccessDeniedException;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.*;import java.util.*;
@Service@RequiredArgsConstructor@Transactional(readOnly=true)
public class QuotationService{private final QuotationRepository quotes;private final WeddingProjectRepository projects;private final WeddingFunctionRepository functions;private final VendorRepository vendors;private final AuthenticatedUserProvider users;
@Transactional public QuotationResponse create(Long projectId,CreateQuotationRequest r){WeddingProject p=staffProject(projectId);Vendor v=vendors.findById(r.vendorId()).orElseThrow(()->new ResourceNotFoundException("Vendor not found: "+r.vendorId()));if(v.getStatus()!=VendorStatus.APPROVED||v.getUser()==null||!v.getUser().isActive())throw new BusinessRuleException("Vendor must be approved and linked to an active account");WeddingFunction f=r.functionId()==null?null:functions.findByIdAndProjectId(r.functionId(),projectId).orElseThrow(()->new BusinessRuleException("Function does not belong to project"));return QuotationResponse.from(quotes.save(QuotationRequest.builder().project(p).function(f).vendor(v).service(r.service().trim()).deadline(r.deadline()).status(QuotationStatus.REQUESTED).build()));}
public List<QuotationResponse> projectQuotes(Long projectId){User u=users.requireCurrentUser();WeddingProject p=projects.findById(projectId).orElseThrow(()->new ResourceNotFoundException("Project not found"));boolean ok=u.getRole()==Role.ADMIN||(u.getRole()==Role.LEAD_PLANNER&&p.getLeadPlanner().getUser().getId().equals(u.getId()))||(u.getRole()==Role.PRIMARY_CLIENT&&p.getPrimaryClient().getUser().getId().equals(u.getId()));if(!ok)throw new AccessDeniedException("Project quotations unavailable");return quotes.findAllByProjectIdOrderByCreatedAtDesc(projectId).stream().map(QuotationResponse::from).toList();}
public List<QuotationResponse> mine(){User u=users.requireCurrentUser();if(u.getRole()!=Role.VENDOR)throw new AccessDeniedException("Vendor only");Vendor v=vendors.findByUserId(u.getId()).orElseThrow(()->new ResourceNotFoundException("Vendor profile not found"));return quotes.findAllByVendorIdOrderByCreatedAtDesc(v.getId()).stream().map(QuotationResponse::from).toList();}
@Transactional public QuotationResponse submit(Long id,SubmitQuotationRequest r){User u=users.requireCurrentUser();QuotationRequest q=entity(id);if(q.getVendor().getUser()==null||!q.getVendor().getUser().getId().equals(u.getId()))throw new AccessDeniedException("Quotation request belongs to another vendor");if(q.getStatus()!=QuotationStatus.REQUESTED)throw new BusinessRuleException("Quotation is not open for submission");if(q.getDeadline().isBefore(LocalDate.now()))throw new BusinessRuleException("Quotation deadline has passed");q.setAmount(r.amount());q.setDescription(r.description().trim());q.setSubmittedAt(Instant.now());q.setStatus(QuotationStatus.SUBMITTED);return QuotationResponse.from(q);}
@Transactional public QuotationResponse decide(Long id,QuotationDecisionRequest r){User u=users.requireCurrentUser();QuotationRequest q=entity(id);if(u.getRole()!=Role.PRIMARY_CLIENT||!q.getProject().getPrimaryClient().getUser().getId().equals(u.getId()))throw new AccessDeniedException("Only the project's primary client can decide");if(q.getStatus()!=QuotationStatus.SUBMITTED)throw new BusinessRuleException("Only submitted quotations can be decided");q.setStatus(Boolean.TRUE.equals(r.approved())?QuotationStatus.APPROVED:QuotationStatus.REJECTED);q.setDecidedBy(u);q.setDecidedAt(Instant.now());if(Boolean.TRUE.equals(r.approved()))for(QuotationRequest other:quotes.findAllByProjectIdOrderByCreatedAtDesc(q.getProject().getId()))if(!other.getId().equals(q.getId())&&sameGroup(q,other)&&(other.getStatus()==QuotationStatus.REQUESTED||other.getStatus()==QuotationStatus.SUBMITTED))other.setStatus(QuotationStatus.CLOSED);return QuotationResponse.from(q);}
private boolean sameGroup(QuotationRequest a,QuotationRequest b){return Objects.equals(a.getFunction()==null?null:a.getFunction().getId(),b.getFunction()==null?null:b.getFunction().getId())&&a.getService().equalsIgnoreCase(b.getService());}private QuotationRequest entity(Long id){return quotes.findById(id).orElseThrow(()->new ResourceNotFoundException("Quotation request not found: "+id));}private WeddingProject staffProject(Long id){User u=users.requireCurrentUser();WeddingProject p=projects.findById(id).orElseThrow(()->new ResourceNotFoundException("Project not found"));if(u.getRole()==Role.ADMIN||(u.getRole()==Role.LEAD_PLANNER&&p.getLeadPlanner().getUser().getId().equals(u.getId())))return p;throw new AccessDeniedException("Project unavailable");}}
